function HasCloseElements(numbers: array of real; threshold: real): boolean;
begin
  var seen := new HashSet<real>;
  foreach var num in numbers do
  begin
    var c := seen.Count(x -> Abs(x - num) < threshold);
    if c > 0 then
    begin
      Result := True;
      exit;
    end;
    seen.Add(num);
  end;
  Result := False;
end;


function SeparateParenGroups(parenString: string): array of string;
begin
  var stack := new Stack<string>;
  var currentGroup := new StringBuilder;
  var groups := new List<string>;
  var ignoreSpace := False;

  foreach var ch in parenString do
  begin
    if ch = ' ' then
    begin
      if ignoreSpace then
        continue;
      ignoreSpace := False;
    end
    else if ch = '(' then
    begin
      if currentGroup.Length > 0 then
      begin
        groups.Add(currentGroup.ToString);
        currentGroup.Clear;
      end;
      currentGroup.Append('(');
    end
    else if ch = ')' then
    begin
      if currentGroup.Length > 0 then
      begin
        groups.Add(currentGroup.ToString);
        currentGroup.Clear;
      end;
      currentGroup.Append(')');
      if currentGroup.Length = 0 then
        groups.Add(currentGroup.ToString)
      else
        currentGroup.Append(')');
    end;
  end;

  Result := groups.ToArray;
end;


