function MakePalindrome(str: string): string;
begin
  var n := str.Length;
  if n <= 1 then
  begin
    Result := str;
    exit;
  end;

  var longest := '';
  for var i := n downto 1 do
  begin
    var suffix := str.Substring(0, i);
    if IsPalindrome(suffix) then
    begin
      longest := suffix;
      break;
    end;
  end;

  if longest.Length = 0 then
  begin
    Result := str;
    exit;
  end;

  var prefix := str.Substring(0, n - longest.Length);
  var reversed := new string(str.Reverse.ToArray);
  var palindrome := reversed.Substring(0, reversed.Length - prefix.Length);

  Result := str + palindrome;
end;


