    end;
    i += 6;
  end;
  Result := True;
end;

function Poly(xs : array of real; x : real): real;
{ Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n }
begin
  var _result := 0.0;
  for var i := 0 to xs.Length - 1 do
    _result := _result + xs[i] * Power(x, i);
  Result := _result;
end;
function FindZero(xs: array of real): real;
begin
  var n := xs.Length;
  if n = 0 then
  begin
    Result := 0;
    exit;
  end;
  if n mod 2 <> 0 then
  begin
    Result := 0;
    exit;
  end;
  var maxCoeff := xs.Max;
  if maxCoeff <= 0 then
  begin
    Result := 0;
    exit;
  end;
  var roots := new List<real>;
  var p := 0;
  var q := 1;
  while q < n do
  begin
    roots.Add((-p - q) / 2.0);
    p := q;
    q := 2 * p + n;
  end;
  var res := 0.0;
  foreach var root in roots do
  begin
    var val := Poly(xs, root);
    if Abs(val) < 1e-10 then
    begin
      Result := root;
      exit;
    end;
    if val > 0 then
      res := root
    else
      res := -root;
  end;
  Result := res;
end;


