function TriplesSumToZero(lst: array of integer): boolean;
begin
  var seen := new HashSet<integer>;
  var sorted := lst.OrderBy(x -> x).ToArray;

  for var i := 0 to sorted.Length - 3 do
  begin
    if (sorted[i] > 0) or (sorted[i] + sorted[i + 1] + sorted[i + 2] > 0) then
      break;

    if (i > 0) and (sorted[i] = sorted[i - 1]) then
      continue;

    var left := i + 1;
    var right := sorted.Length - 1;

    while left < right do
    begin
      var total := sorted[i] + sorted[left] + sorted[right];
      if total = 0 then
      begin
        Result := True;
        exit;
      end
      else if total < 0 then
        left += 1
      else
        right -= 1;

      if (left > i + 1) and (sorted[left] = sorted[left - 1]) then
        left += 1
      else if (right < sorted.Length - 1) and (sorted[right] = sorted[right + 1]) then
        right -= 1;
    end;
  end;

  Result := False;
end;


