function Monotonic(l: array of integer): boolean;
begin
  if l.Length <= 1 then
  begin
    Result := True;
    exit;
  end;
  var increasing := True;
  var decreasing := True;
  for var i := 0 to l.Length - 2 do
  begin
    if l[i] <> l[i + 1] then
    begin
      if l[i] < l[i + 1] then
        decreasing := False
      else
        increasing := False;
    end;
  end;
  Result := increasing or decreasing;
end;


