        end;
        x := i;
        while (x < m) and (grid[x][y] = 1) do
        begin
          buckets[x, y] := buckets[x, y] + 1;
          x := x + 1;
        end;
      end;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i][j] = 0 then
      begin
        var x := i;
        var y := j;
        while (x >= 0) and (buckets[x, y] < capacity) do
        begin
          x := x - 1;
        end;
        if x >= 0 then
          count := count + 1;
        x := i;
        while (x < m) and (buckets[x, y] < capacity) do
        begin
          x := x + 1;
        end;
        if x < m then
          count := count + 1;
      end;

  Result := count;
end;


