function CanArrange(arr: array of integer): integer;
begin
  var count := new Dictionary<integer, integer>;
  var maxIndex := -1;

  foreach var num in arr do
  begin
    if count.ContainsKey(num) then
      count[num] += 1
    else
      count[num] := 1;
  end;

  foreach var num in count.Keys do
  begin
    if not count.ContainsKey(num + 1) then
      continue;

    if (num + 1) mod 2 <> 0 then
      continue;

    if (num + 1) div 2 < count[num + 1] then
      continue;

    if num mod 2 <> 0 then
      continue;

    if num mod 4 = 0 then
    begin
      var v := num div 4;
      if count.ContainsKey(v) and (count[v] > 0) then
      begin
        count[v] -= 1;
        if v > maxIndex then
          maxIndex := v;
      end
      else
      begin
        var vv := v * 2;
        if count.ContainsKey(vv) and (count[vv] > 0) then
        begin
          count[vv] -= 1;
          if vv > maxIndex then
            maxIndex := vv;
        end;
      end;
    end;
  end;

  Result := maxIndex;
end;


