  begin
    case op of
      '+': Result := a + b;
      '-': Result := a - b;
      '*': Result := a * b;
      '//': Result := a div b;
      '**': Result := a * b;
    end;
  end;
begin
  var res := operand[0];
  for var i := 0 to op.Length - 1 do
    res := Calc(res, operand[i + 1], op[i]);
  Result := res;
end;


function Solve(s: string): string;
begin
  var sb := new StringBuilder;
  var letters := new HashSet<char>;

  foreach var ch in s do
  begin
    if char.IsLetter(ch) then
    begin
      if letters.Contains(char.ToLower(ch)) then
        sb.Append(char.ToUpper(ch))
      else
        sb.Append(char.ToLower(ch));
      letters.Add(char.ToLower(ch));
    end
    else
      sb.Append(ch);
  end;

  Result := sb.ToString;
end;


function StringToMd5(text: string): string;
begin
  if text = '' then
  begin
    Result := nil;
    exit;
  end;

  var hasher := new System.Security.Cryptography.MD5CryptoServiceProvider;
  var inputBytes := Encoding.ASCII.GetBytes(text);
  var hash := hasher.ComputeHash(inputBytes);

  var sb := new StringBuilder;
  foreach var b in hash do
    sb.Append(b.ToString('x2'));

  Result := sb.ToString;
end;


function GenerateIntegers(a, b: integer): array of integer;
begin
  var res := new List<integer>;
  for var i := a to b step 2 do
    res.Add(i);
  Result := res.ToArray;
end;
